import { invalidateAttachCache, type AttachedServer } from './client';
import { isPidAlive } from './serverHandshake';

const SHUTDOWN_POLL_MS = 100;
export const DEFAULT_SHUTDOWN_TIMEOUT_MS = 10_000;

export const waitForServerShutdown = async (
  attached: AttachedServer,
  timeoutMs = DEFAULT_SHUTDOWN_TIMEOUT_MS,
): Promise<boolean> => {
  invalidateAttachCache();
  const deadline = Date.now() + timeoutMs;
  while (isPidAlive(attached.handshake.pid)) {
    if (Date.now() >= deadline) return false;
    await new Promise((resolve) => setTimeout(resolve, SHUTDOWN_POLL_MS));
  }
  invalidateAttachCache();
  return true;
};
